#include <iostream>
#include <string>

class Dog {
public:
    Dog(std::string name, int age) : name_(name), age_(age) {
        std::cout << "constructed " << name_ << "\n";
    }
    std::string bark() const { return name_ + " says woof"; }
private:
    std::string name_;
    int age_;
};

int main() {
    Dog rex("Rex", 3);
    Dog* pip = new Dog("Pip", 1);
    std::cout << rex.bark() << "\n";
    delete pip;
}
